#include <stdio.h>
#include <string.h>

/* Same enums as the candidate's file. */
enum signal_aspect    { SIGNAL_GREEN, SIGNAL_RED };
enum barrier_position { BARRIER_UP, BARRIER_MOVING, BARRIER_DOWN };

/* Provided by the candidate in solution.c */
void crossing_command(int approaching, int in_crossing, int barrier,
                      int *signal_out, int *target_out);

int main(void)
{
    int approaching = 0;
    int in_crossing = 0;
    int barrier = BARRIER_UP;
    int target = BARRIER_UP;
    int signal = SIGNAL_RED;

    char event[32];
    int step = 0;

    strcpy(event, "start");

    for (;;) {
        /* 1. the world moves, using the target commanded last time round */
        if (step > 0) {
            if (strcmp(event, "approach") == 0) {
                approaching++;
            } else if (strcmp(event, "enter") == 0) {
                if (approaching > 0) {
                    approaching--;
                }
                in_crossing++;
            } else if (strcmp(event, "exit") == 0) {
                if (in_crossing > 0) {
                    in_crossing--;
                }
            } else if (strcmp(event, "tick") == 0) {
                if (target == BARRIER_DOWN && barrier < BARRIER_DOWN) {
                    barrier++;
                } else if (target == BARRIER_UP && barrier > BARRIER_UP) {
                    barrier--;
                }
            } else {
                printf("UNKNOWN EVENT %s\n", event);
                return 1;
            }
        }

        /* 2. the controller decides */
        signal = -1;
        target = -1;
        crossing_command(approaching, in_crossing, barrier, &signal, &target);

        if (signal != SIGNAL_GREEN && signal != SIGNAL_RED) {
            printf("INVALID signal %d\n", signal);
            return 1;
        }
        if (target != BARRIER_UP && target != BARRIER_DOWN) {
            printf("INVALID barrier target %d\n", target);
            return 1;
        }

        printf("%s %s\n",
               signal == SIGNAL_RED ? "RED" : "GREEN",
               target == BARRIER_DOWN ? "DOWN" : "UP");

        /* 3. the safety monitor. It lives here, out of reach of solution.c,
              for the same reason main() does. */
        if (in_crossing > 0 && barrier != BARRIER_DOWN) {
            printf("UNSAFE at event %d (%s): a train is in the crossing with "
                   "the barrier not down\n", step, event);
            return 0;
        }
        if (signal == SIGNAL_GREEN && barrier != BARRIER_UP) {
            printf("UNSAFE at event %d (%s): the road signal is green with "
                   "the barrier not up\n", step, event);
            return 0;
        }

        /* 4. the next event, if there is one */
        if (scanf("%31s", event) != 1) {
            break;
        }
        step++;
    }

    printf("SAFE\n");
    return 0;
}
